/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
class METDutyAdValorumClaimGenerateService extends SysOperationServiceBase
{
    List                    itemList;
    List                    siteList;
    boolean                 filterItemSite;
    str                     currUser                = curUserId();
    RecordInsertList        recordInsertListItemSite = new RecordInsertList(tableNum(METExciseSiteDutySetup));

}

Method.Source:
    /// <summary>
    /// main process method
    /// </summary>
    /// <param name = "_dataContract">Contract</param>
    public void processOperation(METDutyAdValorumClaimGenerateContract _dataContract)
    {
        METVendClaimProcessHelper   vendClaimProcessHelper;
        METDutyRollVariance     dutyRollVarianceGrouped;
        METDutyRollVariance     dutyRollVariance;
        METDutyRollVariance     dutyRollVarianceDelete;
        METExciseSiteDutySetup  exciseSiteDutySetup;
        METInventTable          metInventTable;
        METTariffItemCode       tariffItemCode;
        RecordInsertList        recordInsertList = new RecordInsertList(tableNum(METExciseSiteDutySetup));
        boolean dutyBySite  = _dataContract.parmDutyValuesBySite();
        boolean generateClaim = _dataContract.parmGenerateClaims();
        UserId                  batchUser = curUserId();

        filterItemSite          = _dataContract.parmFilterItemSite();
        itemList                = _dataContract.parmItemList();
        siteList                = _dataContract.parmSiteList();
        
        if (generateClaim)
        {
            vendClaimProcessHelper = new METVendClaimProcessHelper();
            vendClaimProcessHelper.initParameters();
            vendClaimProcessHelper.initLedgerJournalParm();
            vendClaimProcessHelper.createLedgerJournalTable();
        }

        if (!filterItemSite)
        {
            while select dutyRollVarianceGrouped
                group by ItemId, Site
        
            {
                select firstonly dutyRollVariance
                order by CreatedDateTime
                where dutyRollVariance.ItemId == dutyRollVarianceGrouped.ItemId
                    && dutyRollVariance.Site == dutyRollVarianceGrouped.Site;

                if (dutyBySite)
                {
                    metInventTable = metInventTable::find(dutyRollVariance.ItemId);
                    exciseSiteDutySetup = METExciseSiteDutySetup::find(dutyRollVariance.Site, dutyRollVariance.ItemId);

                    METDutyRollValuesTable dutyRollValuesTable;
                    METDutyRollValuesLine dutyRollValuesLine;

                    select firstonly AverageVFD, TotalDutyPerCase from dutyRollValuesLine
                        exists join dutyRollValuesTable
                        where dutyRollValuesTable.RecId == dutyRollValuesLine.RefRecId
                        && dutyRollValuesLine.Site == dutyRollVarianceGrouped.Site
                        && dutyRollValuesLine.ItemId == dutyRollVarianceGrouped.ItemId
                        && dutyRollValuesTable.Status == METDutyRollStatus::Active;

                    exciseSiteDutySetup.ValueForDuty    = dutyRollValuesLine.AverageVFD;
                    tariffItemCode  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
                    //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))

                    exciseSiteDutySetup.DutyTotal   = dutyRollValuesLine.TotalDutyPerCase;
                    exciseSiteDutySetup.CalcDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
                    exciseSiteDutySetup.RunBy       = batchUser;
                    if (exciseSiteDutySetup.RecId)
                    {
                        ttsbegin;
                        exciseSiteDutySetup.selectForUpdate(true);
                        exciseSiteDutySetup.update();
                        ttscommit;
                    }
                    else
                    {
                        exciseSiteDutySetup.ItemId  = dutyRollVariance.ItemId;
                        exciseSiteDutySetup.SiteId  = dutyRollVariance.Site;
                        recordInsertList.add(exciseSiteDutySetup);
                    }
                }
                if (generateClaim && dutyRollVariance.ClaimAmount != 0)
                {
                    vendClaimProcessHelper.parmDutyRollVariance(dutyRollVariance);
                    vendClaimProcessHelper.processForDutyVariance();
                }
            }
        }
        else
        {
            if (!siteList.empty())
            {
                ListEnumerator iter = siteList.getEnumerator();

                while (iter.moveNext())
                {
                    InventSiteId siteId  = iter.current(); 
                }

                recordInsertListItemSite.insertDatabase();
            }            
        }

        if (dutyBySite & !filterItemSite)
        {
            recordInsertList.insertDatabase();
        }
        if (generateClaim)
        {
            vendClaimProcessHelper.postLedgerJournal();
            delete_from dutyRollVarianceDelete;
        }
    }

    /// <summary>
    /// Process site
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    public void processSite(InventSiteId _siteId)
    {
        if (!itemList.empty())
        {
            ListEnumerator iter = itemList.getEnumerator();

            while (iter.moveNext())
            {
                ItemId itemId  = iter.current();
                this.processItemSite(_siteId, itemId);
            }
        }
    }

    /// <summary>
    /// Process site & item
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    /// <param name = "_itemId">ItemId</param>
    public void processItemSite(InventSiteId _siteId, ItemId _itemId)
    {
        METDutyRollVariance     dutyRollVariance;

        select firstonly dutyRollVariance
            order by CreatedDateTime
            where dutyRollVariance.ItemId == _itemId
                && dutyRollVariance.Site == _siteId;

        if (dutyRollVariance)
        {
            MetInventTable          metInventTable = METInventTable::find(dutyRollVariance.ItemId);
            METExciseSiteDutySetup  exciseSiteDutySetup = METExciseSiteDutySetup::find(dutyRollVariance.Site, dutyRollVariance.ItemId);

            METDutyRollValuesTable dutyRollValuesTable;
            METDutyRollValuesLine dutyRollValuesLine;

            select firstonly AverageVFD, TotalDutyPerCase from dutyRollValuesLine
                exists join dutyRollValuesTable
                where dutyRollValuesTable.RecId == dutyRollValuesLine.RefRecId
                && dutyRollValuesLine.Site == _siteId
                && dutyRollValuesLine.ItemId == _itemId
                && dutyRollValuesTable.Status == METDutyRollStatus::Active;

            exciseSiteDutySetup.ValueForDuty    = dutyRollValuesLine.AverageVFD;
            METTariffItemCode tariffItemCode    = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
            //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))

            exciseSiteDutySetup.DutyTotal   = dutyRollValuesLine.TotalDutyPerCase;
            exciseSiteDutySetup.CalcDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
            exciseSiteDutySetup.RunBy       = currUser;
            if (exciseSiteDutySetup.RecId)
            {
                ttsbegin;
                exciseSiteDutySetup.selectForUpdate(true);
                exciseSiteDutySetup.update();
                ttscommit;
            }
            else
            {
                exciseSiteDutySetup.ItemId  = dutyRollVariance.ItemId;
                exciseSiteDutySetup.SiteId  = dutyRollVariance.Site;
                recordInsertListItemSite.add(exciseSiteDutySetup);
            }
        }
    }
